import { useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import type { AppHandle } from "@app/kit/primitives";

type Props = { app?: AppHandle };

const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif";
const EASE = [0.22, 1, 0.36, 1] as const;

const DEMOS = [
  { label: "Buyer", email: "mira@atelier.test", pw: "thunder-summit-lark-72" },
  { label: "Maker", email: "hale@atelier.test", pw: "lilac-sage-harbor-98" },
  { label: "Curator", email: "clara@atelier.test", pw: "coral-melon-zephyr-40" },
];

const TILES = [
  { src: "/assets/0381c964afef3226.webp", cap: "Stoneware mug", price: "$28", ratio: "aspect-[3/4]", drop: "mt-6 lg:mt-14" },
  { src: "/assets/439d1c55d4639a45.webp", cap: "Walnut board", price: "$78", ratio: "aspect-[3/5]", drop: "mt-0" },
  { src: "/assets/ba8b5f11b2878645.webp", cap: "Carved oak stool", price: "$220", ratio: "aspect-[4/5]", drop: "mt-10 lg:mt-24" },
  { src: "/assets/5550fbf401da4ff4.webp", cap: "Shibori scarf", price: "$85", ratio: "aspect-[3/5]", drop: "mt-3 lg:mt-8" },
  { src: "/assets/53041b88ebeec82d.webp", cap: "Fruit bowl", price: "$64", ratio: "aspect-[3/4]", drop: "mt-12 lg:mt-4" },
];

function GoogleG() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.8 2.4 30.3 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17.5z" />
      <path fill="#FBBC05" d="M10.5 28.7a14.5 14.5 0 0 1 0-9.4l-7.9-6.1a24 24 0 0 0 0 21.6l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.5-5.8c-2.1 1.4-4.9 2.3-8.4 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
    </svg>
  );
}

export default function AtelierLogin({ app }: Props) {
  const reduce = useReducedMotion();
  const auth = app?.auth;
  const signup = auth?.mode === "signup";
  const providers = auth?.providers ?? [];
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const go = async () => {
    if (!auth || busy) return;
    setBusy(true);
    setError("");
    try {
      if (signup) await auth.signUp({ name: name.trim() || email.split("@")[0], email: email.trim(), password });
      else await auth.signIn(email.trim(), password);
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't work. Please check your details.");
    } finally {
      setBusy(false);
    }
  };

  const provider = async (pname: string) => {
    setError("");
    try {
      await auth?.startProvider(pname);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Couldn't start that sign-in. Please try again.");
    }
  };

  const field =
    "w-full border-0 border-b border-[#CDBDA9] bg-transparent px-0 py-3 text-[15px] text-[#2B2420] placeholder:text-[#B3A593] outline-none transition focus:border-[hsl(var(--primary))]";
  const lbl = "block text-[10px] uppercase tracking-[0.28em] text-[#9A8B7B]";

  return (
    <div className="min-h-screen w-full overflow-x-hidden bg-[#FBF7F2] text-[#2B2420]" style={{ fontFamily: "ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif" }}>
      <div className="mx-auto max-w-[1360px] px-5 pb-12 pt-5 lg:px-12 lg:pt-8">
        <div className="flex items-center justify-between border-b border-[#2B2420] pb-2 text-[10px] uppercase tracking-[0.3em] text-[#6B5E51]">
          <span>Atelier · The handmade issue</span>
          <span className="hidden sm:inline">Autumn · Vol. 07</span>
          <span style={{ color: "hsl(var(--primary))" }}>No. 01</span>
        </div>

        <motion.h1
          initial={reduce ? false : { opacity: 0, y: 36 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, ease: EASE }}
          className="mt-3 text-center leading-[0.9] tracking-[-0.03em] text-[22vw] sm:text-[17vw] lg:text-[190px]"
          style={{ fontFamily: SERIF }}
        >
          Made by <em className="font-normal italic" style={{ color: "hsl(var(--primary))" }}>hand.</em>
        </motion.h1>
        <div className="mt-2 flex items-center justify-between border-y border-[#E3D6C4] py-2 text-[11px] uppercase tracking-[0.24em] text-[#8A7B6B]">
          <span>Ceramics</span><span>Woodwork</span><span>Textiles</span><span className="hidden sm:inline">Candles</span><span className="hidden sm:inline">Jewellery</span>
        </div>

        <div className="mt-6 grid gap-8 lg:mt-8 lg:grid-cols-[1fr_340px] lg:gap-14">
          <div className="grid grid-cols-5 items-start gap-2 sm:gap-4 lg:order-1">
            {TILES.map((t, i) => (
              <motion.figure
                key={t.src}
                initial={reduce ? false : { opacity: 0, y: 40 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.25 + i * 0.1, duration: 0.8, ease: EASE }}
                whileHover={reduce ? undefined : { y: -6 }}
                className={"min-w-0 " + t.drop}
              >
                <div className={"relative w-full overflow-hidden rounded-[10px] shadow-[0_18px_36px_-22px_rgba(60,40,20,0.6)] sm:rounded-2xl " + t.ratio} style={{ background: "linear-gradient(135deg,#EADFD0,#D9C7B0)" }}>
                  <img src={t.src} alt={t.cap} loading="eager" className="absolute inset-0 h-full w-full object-cover" />
                </div>
                <figcaption className="mt-2 hidden sm:block">
                  <span className="block truncate text-[15px] leading-tight" style={{ fontFamily: SERIF }}>{t.cap}</span>
                  <span className="text-xs text-[#9A8B7B]">{t.price}</span>
                </figcaption>
              </motion.figure>
            ))}
          </div>

          <motion.aside
            initial={reduce ? false : { opacity: 0, y: 24 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5, duration: 0.8, ease: EASE }}
            className="lg:order-2 lg:border-l lg:border-[#E3D6C4] lg:pl-10"
          >
            <AnimatePresence mode="wait" initial={false}>
              <motion.div key={signup ? "s" : "l"} initial={reduce ? false : { opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={reduce ? undefined : { opacity: 0, x: -10 }} transition={{ duration: 0.2 }}>
                <p className="text-[10px] uppercase tracking-[0.3em]" style={{ color: "hsl(var(--primary))" }}>{signup ? "Subscribe" : "Members"}</p>
                <h2 className="mt-1 text-[32px] leading-tight" style={{ fontFamily: SERIF }}>{signup ? "Join the studio" : "Welcome back"}</h2>
                <p className="mt-1 text-sm text-[#7A6C5E]">{signup ? "Save pieces and follow the makers you love." : "Sign in to browse, order and run your studio."}</p>
              </motion.div>
            </AnimatePresence>

            <div className="mt-5 space-y-4">
              <AnimatePresence initial={false}>
                {signup && (
                  <motion.div key="name" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                    <label className={lbl}>Name</label>
                    <input aria-label="Name" type="text" placeholder="Your name" value={name} onChange={(e) => setName(e.target.value)} className={field} />
                  </motion.div>
                )}
              </AnimatePresence>
              <div>
                <label className={lbl}>Email</label>
                <input aria-label="Email" type="email" autoComplete="email" placeholder="you@example.com" value={email} onChange={(e) => setEmail(e.target.value)} className={field} />
              </div>
              <div>
                <label className={lbl}>Password</label>
                <input aria-label="Password" type="password" autoComplete={signup ? "new-password" : "current-password"} placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void go(); }} className={field} />
              </div>
            </div>

            <AnimatePresence>
              {error && (
                <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mt-4 bg-[#F6E3DC] px-3.5 py-2.5 text-sm text-[#8C3A25]" role="alert">{error}</motion.p>
              )}
            </AnimatePresence>

            <motion.button
              whileHover={reduce ? undefined : { y: -1 }}
              whileTap={reduce ? undefined : { scale: 0.98 }}
              onClick={() => void go()}
              disabled={busy}
              className="mt-6 w-full rounded-full px-5 py-3.5 text-[15px] font-medium text-white shadow-[0_12px_26px_-12px_rgba(181,131,90,0.95)] disabled:opacity-60"
              style={{ background: "hsl(var(--primary))" }}
            >
              {busy ? "One moment…" : signup ? "Create account" : "Sign in"}
            </motion.button>

            {providers.length > 0 && (
              <>
                <div className="my-5 flex items-center gap-3 text-[10px] uppercase tracking-[0.3em] text-[#B3A593]">
                  <span className="h-px flex-1 bg-[#E3D6C4]" />or<span className="h-px flex-1 bg-[#E3D6C4]" />
                </div>
                <div className="space-y-2.5">
                  {providers.map((p) => (
                    <motion.button
                      key={p.name}
                      type="button"
                      whileTap={reduce ? undefined : { scale: 0.98 }}
                      onClick={() => void provider(p.name)}
                      className="flex w-full items-center justify-center gap-3 rounded-full border border-[#D8C9B5] bg-white px-5 py-3 text-[15px] font-medium text-[#2B2420] transition hover:border-[hsl(var(--primary))]"
                    >
                      {p.name === "google" ? <GoogleG /> : null}
                      Continue with {p.label}
                    </motion.button>
                  ))}
                </div>
              </>
            )}

            {auth?.canSignUp !== false && (
              <p className="mt-5 text-sm text-[#7A6C5E]">
                {signup ? "Already a member?" : "New to Atelier?"}{" "}
                <button type="button" onClick={() => { setError(""); auth?.setMode(signup ? "login" : "signup"); }} className="font-medium underline decoration-[#D9B99A] underline-offset-4" style={{ color: "hsl(var(--primary))" }}>
                  {signup ? "Sign in instead" : "Create an account"}
                </button>
              </p>
            )}

            {!signup && (
              <div className="mt-6 border-t border-[#E3D6C4] pt-4">
                <p className="mb-2.5 text-[10px] uppercase tracking-[0.28em] text-[#9A8B7B]">Try a demo</p>
                <div className="flex flex-wrap gap-2">
                  {DEMOS.map((d) => (
                    <motion.button key={d.label} type="button" whileTap={reduce ? undefined : { scale: 0.94 }} onClick={() => { setEmail(d.email); setPassword(d.pw); setError(""); }} className="rounded-full border border-[#E0D2BF] px-4 py-1.5 text-sm text-[#5C4F43] transition hover:border-[hsl(var(--primary))]">
                      {d.label}
                    </motion.button>
                  ))}
                </div>
              </div>
            )}
          </motion.aside>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence, LayoutGroup, animate, useReducedMotion } from "motion/react";
import { ShoppingBag, Search, X, Plus, ArrowLeft, ChevronLeft, ChevronRight, Check, Package, Truck, CreditCard, Home, LogOut, MapPin, Sparkles } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle; initialView?: string };

const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif";
const INK = "#2B2420";
const SAND = "#FBF7F2";
const SAGE = "#8A9A82";
const CLAY = "hsl(var(--primary))";
const EASE = [0.22, 1, 0.36, 1] as const;
const SH = "shadow-[0_1px_2px_rgba(60,40,20,0.06),0_16px_36px_-20px_rgba(60,40,20,0.45)]";
const CATS = ["all", "ceramics", "woodwork", "textiles", "knitwear", "candles", "jewellery"];
const CTA = "shadow-[0_14px_28px_-12px_rgba(181,131,90,0.95)]";

const s = (r: R | undefined, k: string): string => (r && r[k] != null ? String(r[k]) : "");
const n = (r: R | undefined, k: string): number => (r ? Number(r[k]) || 0 : 0);
const money = (v: number) => "$" + v.toLocaleString("en-US", { minimumFractionDigits: v % 1 ? 2 : 0, maximumFractionDigits: 2 });
const cap = (t: string) => t.charAt(0).toUpperCase() + t.slice(1);

function Counter({ value }: { value: number }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(value);
  const last = useRef(value);
  useEffect(() => {
    if (reduce) { last.current = value; setV(value); return; }
    const c = animate(last.current, value, { duration: 0.7, ease: "easeOut", onUpdate: (x) => { last.current = x; setV(x); } });
    return () => c.stop();
  }, [value, reduce]);
  return <>{"$" + Math.round(v).toLocaleString("en-US")}</>;
}

function StockBadge({ stock }: { stock: number }) {
  const out = stock <= 0;
  const low = stock > 0 && stock <= 5;
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium backdrop-blur" style={{ background: out ? "rgba(43,36,32,0.8)" : low ? "rgba(181,131,90,0.95)" : "rgba(251,247,242,0.92)", color: out || low ? "#fff" : "#4F5E48" }}>
      <span className="h-1.5 w-1.5 rounded-full" style={{ background: out ? "#bbb" : low ? "#fff" : SAGE }} />
      {out ? "Sold out" : low ? "Only " + stock + " left" : stock + " in stock"}
    </span>
  );
}

function Img({ src, className, alt }: { src: string; className?: string; alt: string }) {
  return (
    <div className={"relative overflow-hidden " + (className || "")} style={{ background: "linear-gradient(135deg,#EADFD0,#D9C7B0)" }}>
      {src ? <img src={src} alt={alt} loading="lazy" className="absolute inset-0 h-full w-full object-cover" /> : null}
    </div>
  );
}

function Mono({ name, className }: { name: string; className?: string }) {
  return <div className={"grid place-items-center text-xl text-white " + (className || "")} style={{ background: "linear-gradient(135deg,#C9A27F,#8A9A82)", fontFamily: SERIF }}>{name.charAt(0)}</div>;
}

const STEPS = [
  { key: "placed", label: "Placed", Icon: Check },
  { key: "paid", label: "Paid", Icon: CreditCard },
  { key: "shipped", label: "Shipped", Icon: Truck },
  { key: "delivered", label: "Delivered", Icon: Home },
];

function Timeline({ status }: { status: string }) {
  const reduce = useReducedMotion();
  const idx = Math.max(0, STEPS.findIndex((x) => x.key === status));
  return (
    <div className="relative mt-5 px-1">
      <div className="absolute left-[12.5%] right-[12.5%] top-[17px] h-[3px] rounded-full bg-[#EADFD0]" />
      <motion.div className="absolute left-[12.5%] top-[17px] h-[3px] rounded-full" style={{ background: CLAY }} initial={reduce ? false : { width: 0 }} animate={{ width: (idx / 3) * 75 + "%" }} transition={{ duration: 1, ease: EASE, delay: 0.2 }} />
      <div className="relative grid grid-cols-4">
        {STEPS.map((st, i) => {
          const on = i <= idx;
          return (
            <div key={st.key} className="flex flex-col items-center gap-2">
              <motion.div initial={reduce ? false : { scale: 0.6 }} animate={{ scale: 1 }} transition={{ type: "spring", stiffness: 400, damping: 18, delay: 0.1 + i * 0.1 }} className="grid h-9 w-9 place-items-center rounded-full border-2" style={{ background: on ? CLAY : SAND, borderColor: on ? "transparent" : "#E3D6C4", color: on ? "#fff" : "#B3A593" }}>
                <st.Icon size={15} />
              </motion.div>
              <span className="text-[11px] font-medium" style={{ color: on ? INK : "#B3A593" }}>{st.label}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function Stepper({ value, onChange, size = 28 }: { value: number; onChange: (v: number) => void; size?: number }) {
  const b = "grid place-items-center rounded-full bg-white text-base leading-none";
  return (
    <div className="flex items-center gap-1 rounded-full bg-[#F1E6D8] p-0.5">
      <motion.button whileTap={{ scale: 0.85 }} onClick={() => onChange(value - 1)} aria-label="Less" className={b} style={{ width: size, height: size }}>−</motion.button>
      <span className="w-7 text-center text-sm font-medium">{value}</span>
      <motion.button whileTap={{ scale: 0.85 }} onClick={() => onChange(value + 1)} aria-label="More" className={b} style={{ width: size, height: size }}>+</motion.button>
    </div>
  );
}

export default function Storefront({ app, initialView }: Props) {
  const reduce = useReducedMotion();
  const isSeller = app?.user.role === "seller";
  const [view, setView] = useState<string>(initialView === "orders" ? "orders" : "shop");
  const [cat, setCat] = useState("all");
  const [q, setQ] = useState("");
  const [maker, setMaker] = useState("");
  const [openId, setOpenId] = useState("");
  const [cartOpen, setCartOpen] = useState(false);
  const [toasts, setToasts] = useState<{ id: number; text: string; bad?: boolean }[]>([]);
  const [address, setAddress] = useState("");
  const [placing, setPlacing] = useState(false);
  const [done, setDone] = useState(0);
  const tid = useRef(1);
  const collection = useRef<HTMLDivElement>(null);

  const sellers = (app?.rows("seller") ?? []) as R[];
  const allProducts = (app?.rows("product") ?? []) as R[];
  const cart = (app?.rows("cart_item") ?? []) as R[];
  const orders = (app?.rows("order") ?? []) as R[];
  const loading = app?.loading("product") ?? false;
  const products = useMemo(() => allProducts.filter((p) => s(p, "status") === "approved"), [allProducts]);
  const byId = useMemo(() => { const m: Record<string, R> = {}; for (const p of allProducts) m[s(p, "id")] = p; return m; }, [allProducts]);
  const sellerById = useMemo(() => { const m: Record<string, R> = {}; for (const x of sellers) m[s(x, "id")] = x; return m; }, [sellers]);

  const toast = (text: string, bad?: boolean) => {
    const id = tid.current++;
    setToasts((t) => [...t, { id, text, bad }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3800);
  };
  const toCollection = () => collection.current?.scrollIntoView({ behavior: "smooth" });

  const filtered = useMemo(() => {
    const t = q.trim().toLowerCase();
    return products.filter((p) => (cat === "all" || s(p, "category") === cat) && (!maker || s(p, "seller_id") === maker) && (!t || (s(p, "title") + " " + s(sellerById[s(p, "seller_id")], "shop_name")).toLowerCase().includes(t)));
  }, [products, cat, maker, q, sellerById]);

  const lines = cart.map((c) => ({ c, p: byId[s(c, "product_id")] })).filter((l) => l.p);
  const count = lines.reduce((a, l) => a + n(l.c, "quantity"), 0);
  const subtotal = lines.reduce((a, l) => a + n(l.c, "quantity") * n(l.p, "price"), 0);
  const featured = sellers.filter((x) => x["featured"] === true || x["featured"] === "true");
  const makers = featured.length ? featured : sellers.slice(0, 4);
  const openP = openId ? byId[openId] : undefined;
  const makerRow = maker ? sellerById[maker] : undefined;
  const heroP = products.slice().sort((a, b) => n(b, "price") - n(a, "price"))[0];
  const coverOf = (m: R) => s(products.find((p) => s(p, "seller_id") === s(m, "id")), "photo");

  const addToCart = async (p: R, qty: number) => {
    const stock = n(p, "stock");
    if (stock <= 0) { toast("That piece is sold out", true); return; }
    const existing = cart.find((c) => s(c, "product_id") === s(p, "id"));
    const next = Math.min(stock, (existing ? n(existing, "quantity") : 0) + qty);
    try {
      if (existing) await app?.update("cart_item", s(existing, "id"), { quantity: next });
      else await app?.create("cart_item", { product_id: s(p, "id"), quantity: next, buyer_id: app?.me("buyer") });
      toast(s(p, "title") + " added to your bag");
    } catch (e) { toast(e instanceof Error ? e.message : "Couldn't add to bag", true); }
  };
  const setQty = async (c: R, p: R, qty: number) => {
    if (qty <= 0) { await app?.remove("cart_item", s(c, "id")); return; }
    if (qty > n(p, "stock")) { toast("Only " + n(p, "stock") + " available", true); return; }
    await app?.update("cart_item", s(c, "id"), { quantity: qty });
  };
  const checkout = async () => {
    if (placing || !lines.length) return;
    setPlacing(true);
    const today = new Date().toISOString().slice(0, 10);
    let ok = 0;
    for (const l of lines) {
      try {
        await app?.create("order", { buyer_id: app?.me("buyer"), seller_id: s(l.p, "seller_id"), product_id: s(l.p, "id"), product_title: s(l.p, "title"), quantity: n(l.c, "quantity"), total: n(l.c, "quantity") * n(l.p, "price"), status: "placed", placed_on: today, ship_to: address.trim() || "Address to be confirmed" });
        await app?.remove("cart_item", s(l.c, "id"));
        ok++;
      } catch (e) {
        toast(e instanceof Error ? e.message : "Order refused", true);
      }
    }
    setPlacing(false);
    if (ok) setDone(ok);
  };

  const myOrders = orders.slice().sort((a, b) => (s(b, "placed_on") + s(b, "created_at")).localeCompare(s(a, "placed_on") + s(a, "created_at")));
  const nav = [{ id: "shop", label: "Shop", Icon: Sparkles }, ...(!isSeller ? [{ id: "orders", label: "My orders", Icon: Package }] : [])];
  const go = (id: string) => { setOpenId(""); setView(id); };
  const openStudio = () => app?.navigate("/studio");

  return (
    <div className="min-h-screen w-full pb-28 lg:pb-16" style={{ background: SAND, color: INK, fontFamily: "ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif" }}>
      <header className="sticky top-0 z-30 border-b border-[#EADFD0]/70 backdrop-blur-xl" style={{ background: "rgba(251,247,242,0.82)" }}>
