                <button onClick={() => step(1)} aria-label="Next photo" className="absolute right-3 top-1/2 grid h-10 w-10 -translate-y-1/2 place-items-center rounded-full bg-white/85 shadow"><ChevronRight size={18} /></button>
                <div className="absolute bottom-4 left-1/2 flex -translate-x-1/2 gap-1.5 rounded-full bg-black/25 px-2.5 py-1.5 backdrop-blur">
                  {photos.map((_, i) => <motion.span key={i} animate={{ width: i === idx ? 18 : 6, opacity: i === idx ? 1 : 0.6 }} className="h-1.5 rounded-full bg-white" />)}
                </div>
