          </motion.div>
          <div className="mt-4 flex gap-3">
            {photos.map((ph, i) => (
              <motion.button key={i} whileTap={{ scale: 0.94 }} onClick={() => pick(i)} aria-label={"Photo " + (i + 1)} className="relative h-20 w-20 overflow-hidden rounded-2xl" style={{ outline: i === idx ? "2px solid " + CLAY : "2px solid transparent", outlineOffset: 2 }}>
                <img src={ph} alt="" className="h-full w-full object-cover" />
