        </div>

        <motion.div initial={reduce ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.15, duration: 0.6, ease: EASE }}>
          <p className="text-[11px] uppercase tracking-[0.3em] text-[#9A8B7B]">{cap(s(p, "category"))}</p>
          <h1 className="mt-2 text-4xl leading-[1.05] lg:text-5xl" style={{ fontFamily: SERIF }}>{s(p, "title")}</h1>
          <div className="mt-4 flex items-center gap-4">
            <span className="text-3xl" style={{ fontFamily: SERIF }}>{money(n(p, "price"))}</span>
            <span className="rounded-full bg-[#F1E6D8]"><StockBadge stock={stock} /></span>
