          <div className="mt-7 flex items-center gap-3">
            <Stepper value={qty} size={40} onChange={(v) => setQty(Math.min(Math.max(1, stock), Math.max(1, v)))} />
            <motion.button whileHover={{ y: -2 }} whileTap={{ scale: 0.96 }} transition={{ type: "spring", stiffness: 500, damping: 24 }} disabled={stock <= 0} onClick={() => onAdd(qty, false)} className="flex-1 rounded-full border-2 border-[#2B2420] py-3.5 text-[15px] font-medium disabled:opacity-40">Add to bag</motion.button>
          </div>
          <motion.button whileHover={{ y: -2 }} whileTap={{ scale: 0.97 }} disabled={stock <= 0} onClick={() => onAdd(qty, true)} className={"mt-3 w-full rounded-full py-4 text-[15px] font-medium text-white disabled:opacity-40 " + CTA} style={{ background: CLAY }}>{stock <= 0 ? "Currently sold out" : "Buy now · " + money(qty * n(p, "price"))}</motion.button>

          {maker && (
            <div className="mt-10 rounded-[28px] bg-[#F1E6D8] p-6">
              <p className="mb-3 text-[11px] uppercase tracking-[0.28em] text-[#9A8B7B]">Meet the maker</p>
              <div className="flex items-center gap-4">
                <Mono name={s(maker, "shop_name")} className="h-16 w-16 shrink-0 rounded-full" />
                <div>
                  <p className="text-xl leading-tight" style={{ fontFamily: SERIF }}>{s(maker, "shop_name")}</p>
                  <p className="flex items-center gap-1 text-sm text-[#8A7B6B]"><MapPin size={13} />{s(maker, "name")} · {s(maker, "location")}</p>
                </div>
              </div>
              <p className="mt-4 text-[15px] leading-relaxed text-[#5C4F43]">{s(maker, "story")}</p>
              <button onClick={onMaker} className="mt-4 text-sm font-medium underline underline-offset-4" style={{ color: CLAY }}>See everything from {s(maker, "shop_name")}</button>
            </div>
          )}
        </motion.div>
      </div>
    </motion.div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence, LayoutGroup, animate, useReducedMotion } from "motion/react";
import { LayoutDashboard, Package, Truck, ShoppingBag, LogOut, Plus, Pencil, X, Check, Clock, TrendingUp, Home, Sparkles } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle };

const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif";
const INK = "#2B2420";
const SAND = "#FBF7F2";
const SAGE = "#8A9A82";
const CLAY = "hsl(var(--primary))";
const EASE = [0.22, 1, 0.36, 1] as const;
const SH = "shadow-[0_1px_2px_rgba(60,40,20,0.06),0_16px_36px_-20px_rgba(60,40,20,0.45)]";
const CATS = ["ceramics", "woodwork", "textiles", "knitwear", "candles", "jewellery"];

const s = (r: R | undefined, k: string): string => (r && r[k] != null ? String(r[k]) : "");
const n = (r: R | undefined, k: string): number => (r ? Number(r[k]) || 0 : 0);
const money = (v: number) => "$" + v.toLocaleString("en-US", { maximumFractionDigits: 0 });
const cap = (t: string) => t.charAt(0).toUpperCase() + t.slice(1);

function Counter({ value, size }: { value: number; size?: string }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(0);
  const last = useRef(0);
  useEffect(() => {
    if (reduce) { last.current = value; setV(value); return; }
    const c = animate(last.current, value, { duration: 1.2, ease: "easeOut", onUpdate: (x) => { last.current = x; setV(x); } });
    return () => c.stop();
  }, [value, reduce]);
  return <span className={size} style={{ fontFamily: SERIF }}>{money(v)}</span>;
}

function Img({ src, className, alt }: { src: string; className?: string; alt: string }) {
  return (
    <div className={"relative overflow-hidden " + (className || "")} style={{ background: "linear-gradient(135deg,#EADFD0,#D9C7B0)" }}>
      {src ? <img src={src} alt={alt} loading="lazy" className="absolute inset-0 h-full w-full object-cover" /> : null}
    </div>
  );
}

function Pill({ status }: { status: string }) {
  const map: Record<string, [string, string]> = {
    approved: ["rgba(138,154,130,0.25)", "#4F5E48"], pending: ["#F6E7C9", "#8A6420"], hidden: ["#ECE6DF", "#7A6C5E"],
    placed: ["#F6E7C9", "#8A6420"], paid: ["rgba(181,131,90,0.2)", "#8A5E3B"], shipped: ["rgba(138,154,130,0.25)", "#4F5E48"], delivered: ["rgba(138,154,130,0.25)", "#4F5E48"],
  };
  const [bg, fg] = map[status] || ["#ECE6DF", "#7A6C5E"];
  return <span className="rounded-full px-2.5 py-1 text-[11px] font-medium" style={{ background: bg, color: fg }}>{cap(status)}</span>;
}

const EMPTY = { title: "", description: "", category: "ceramics", price: "", stock: "", photo: "", photo_2: "", photo_3: "", materials: "" };

export default function Studio({ app }: Props) {
  const reduce = useReducedMotion();
  const [tab, setTab] = useState("overview");
  const [month, setMonth] = useState("");
  const [filter, setFilter] = useState("all");
  const [sheet, setSheet] = useState<null | { id: string }>(null);
  const [form, setForm] = useState<Record<string, string>>(EMPTY);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState<{ text: string; bad?: boolean } | null>(null);
  const [busy, setBusy] = useState("");
  const [aiBusy, setAiBusy] = useState(false);
  const [aiDraft, setAiDraft] = useState("");
  const [aiNote, setAiNote] = useState("");

  useEffect(() => { setMonth(new Date().toISOString().slice(0, 7)); }, []);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(null), 3400); return () => clearTimeout(t); }, [toast]);

  const me = app?.me("seller");
  const sellers = (app?.rows("seller") ?? []) as R[];
  const mine = sellers.find((x) => s(x, "id") === me);
  const products = ((app?.rows("product") ?? []) as R[]).filter((p) => s(p, "seller_id") === me);
  const orders = ((app?.rows("order") ?? []) as R[]).filter((o) => s(o, "seller_id") === me).sort((a, b) => (s(b, "placed_on") + s(b, "created_at")).localeCompare(s(a, "placed_on") + s(a, "created_at")));
  const buyers = (app?.rows("buyer") ?? []) as R[];
  const buyerName = (id: string) => s(buyers.find((b) => s(b, "id") === id), "name") || "Customer";
  const loading = app?.loading("order") ?? false;

  const earned = (o: R) => ["paid", "shipped", "delivered"].includes(s(o, "status"));
  const monthEarn = useMemo(() => orders.filter((o) => earned(o) && month && s(o, "placed_on").startsWith(month)).reduce((a, o) => a + n(o, "total"), 0), [orders, month]);
  const lastMonthEarn = useMemo(() => orders.filter((o) => earned(o) && month && !s(o, "placed_on").startsWith(month)).reduce((a, o) => a + n(o, "total"), 0), [orders, month]);
  const toShip = orders.filter((o) => s(o, "status") === "paid").length;
  const live = products.filter((p) => s(p, "status") === "approved").length;
  const pending = products.filter((p) => s(p, "status") === "pending").length;
  const shown = orders.filter((o) => filter === "all" || s(o, "status") === filter);
  const byId = useMemo(() => { const m: Record<string, R> = {}; for (const p of (app?.rows("product") ?? []) as R[]) m[s(p, "id")] = p; return m; }, [app, products.length]);

  const weeks = useMemo(() => {
    const out: { label: string; value: number }[] = [];
    const buckets = ["Wk 1", "Wk 2", "Wk 3", "Wk 4"];
    buckets.forEach((b, i) => out.push({ label: b, value: orders.filter((o) => earned(o) && month && s(o, "placed_on").startsWith(month) && Math.min(3, Math.floor((Number(s(o, "placed_on").slice(8, 10)) - 1) / 8)) === i).reduce((a, o) => a + n(o, "total"), 0) }));
    return out;
  }, [orders, month]);
  const maxWeek = Math.max(1, ...weeks.map((w) => w.value));

  const flash = (text: string, bad?: boolean) => setToast({ text, bad });
  const openSheet = (p?: R) => {
    setForm(p ? { title: s(p, "title"), description: s(p, "description"), category: s(p, "category") || "ceramics", price: s(p, "price"), stock: s(p, "stock"), photo: s(p, "photo"), photo_2: s(p, "photo_2"), photo_3: s(p, "photo_3"), materials: s(p, "materials") } : EMPTY);
    setAiDraft(""); setAiNote("");
    setSheet({ id: p ? s(p, "id") : "" });
  };
  const save = async () => {
    if (saving) return;
    if (!form.title.trim() || !form.photo.trim() || !(Number(form.price) >= 0) || form.price === "") { flash("Add a title, price and a photo URL", true); return; }
    setSaving(true);
    const values: R = { title: form.title.trim(), description: form.description.trim() || "Handmade with care.", category: form.category, price: Number(form.price), stock: Math.max(0, Number(form.stock) || 0), photo: form.photo.trim(), photo_2: form.photo_2.trim() || undefined, photo_3: form.photo_3.trim() || undefined, materials: form.materials.trim() || undefined };
    try {
      if (sheet && sheet.id) { await app?.update("product", sheet.id, values); flash("Changes saved"); }
      else { await app?.create("product", { ...values, seller_id: me, status: "pending" }); flash("Sent for curator approval"); }
      setSheet(null);
    } catch (e) { flash(e instanceof Error ? e.message : "Couldn't save", true); }
    setSaving(false);
  };
  const describe = async () => {
    if (aiBusy) return;
    if (!form.title.trim()) { setAiNote("Add a title first so I know what I'm describing."); return; }
    setAiBusy(true); setAiNote(""); setAiDraft("");
    try {
      const prompt = "Title: " + form.title.trim() + "\nCategory: " + form.category + "\nMaterials: " + (form.materials.trim() || "not given");
      const text = await app?.ai.ask(prompt, { system: "You write product copy for a handmade marketplace. Reply with exactly two warm, specific sentences describing the piece for a buyer. No title, no quotes, no emoji, no invented facts beyond the materials given.", maxTokens: 160 });
      const clean = (text || "").trim();
      if (!clean) throw new Error("empty");
      setAiDraft(clean);
    } catch { setAiNote("AI is resting right now, try again soon."); }
    setAiBusy(false);
  };
  const advance = async (o: R, to: string) => {
    setBusy(s(o, "id"));
    try {
      try { await app?.transition("order", s(o, "id"), "status", to); }
      catch { await app?.update("order", s(o, "id"), { status: to }); }
      flash(to === "shipped" ? "Marked as shipped" : "Marked as delivered");
    } catch (e) { flash(e instanceof Error ? e.message : "Couldn't update", true); }
    setBusy("");
  };

  const nav = [
    { id: "overview", label: "Overview", Icon: LayoutDashboard },
    { id: "products", label: "Products", Icon: Package },
    { id: "orders", label: "Orders", Icon: Truck, badge: toShip },
  ];
  const input = "w-full rounded-2xl border border-[#E6DACB] bg-white px-4 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]";

  return (
    <div className="min-h-screen w-full lg:grid lg:grid-cols-[250px_1fr]" style={{ background: SAND, color: INK, fontFamily: "ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif" }}>
      <aside className="hidden border-r border-[#EADFD0] bg-[#F7F0E7] p-6 lg:flex lg:min-h-screen lg:flex-col">
        <div className="flex items-center gap-2.5">
          <span className="grid h-9 w-9 place-items-center rounded-full text-lg text-white" style={{ background: CLAY, fontFamily: SERIF }}>A</span>
          <span className="text-2xl" style={{ fontFamily: SERIF }}>Studio</span>
        </div>
        <LayoutGroup id="side">
          <nav className="mt-10 space-y-1">
            {nav.map((t) => (
              <button key={t.id} onClick={() => setTab(t.id)} className="relative flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm font-medium" style={{ color: tab === t.id ? INK : "#8A7B6B" }}>
                {tab === t.id && <motion.span layoutId="sidepill" className="absolute inset-0 rounded-2xl bg-white shadow-sm" transition={{ type: "spring", stiffness: 420, damping: 34 }} />}
                <t.Icon size={18} className="relative" /><span className="relative">{t.label}</span>
                {t.badge ? <span className="relative ml-auto rounded-full px-2 py-0.5 text-[11px] text-white" style={{ background: CLAY }}>{t.badge}</span> : null}
              </button>
            ))}
          </nav>
        </LayoutGroup>
        <div className="mt-auto space-y-1">
          <button onClick={() => app?.navigate("/shop")} className="flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm text-[#8A7B6B]"><ShoppingBag size={18} />Visit the shop</button>
          <button onClick={() => void app?.auth.signOut()} className="flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm text-[#8A7B6B]"><LogOut size={18} />Sign out</button>
        </div>
      </aside>

      <div className="min-w-0 pb-28 lg:pb-12">
        <header className="flex items-center justify-between px-5 pb-2 pt-6 lg:px-10 lg:pt-9">
          <div className="flex items-center gap-3">
            <div className="grid h-12 w-12 place-items-center rounded-full text-xl text-white" style={{ background: "linear-gradient(135deg,#C9A27F,#8A9A82)", fontFamily: SERIF }}>{s(mine, "shop_name").charAt(0) || "A"}</div>
            <div>
              <p className="text-[11px] uppercase tracking-[0.28em] text-[#9A8B7B]">Your studio</p>
              <h1 className="text-2xl leading-tight lg:text-3xl" style={{ fontFamily: SERIF }}>{s(mine, "shop_name") || "Studio"}</h1>
            </div>
          </div>
          <div className="flex gap-2 lg:hidden">
            <button onClick={() => app?.navigate("/shop")} aria-label="Visit shop" className="grid h-11 w-11 place-items-center rounded-full border border-[#EADFD0] bg-white"><ShoppingBag size={18} /></button>
            <button onClick={() => void app?.auth.signOut()} aria-label="Sign out" className="grid h-11 w-11 place-items-center rounded-full border border-[#EADFD0] bg-white text-[#8A7B6B]"><LogOut size={18} /></button>
