                  <div className="relative overflow-hidden rounded-[32px] p-7 text-[#FBF7F2] lg:p-9" style={{ background: "linear-gradient(135deg,#B5835A,#8E6240 70%,#6F7B68)" }}>
                    <p className="text-[11px] uppercase tracking-[0.3em] opacity-80">Earned this month</p>
