                      <Img src={s(byId[s(o, "product_id")], "photo")} alt="" className="h-14 w-14 shrink-0 rounded-2xl" />
                      <div className="min-w-0 flex-1"><p className="truncate text-[15px]" style={{ fontFamily: SERIF }}>{s(o, "product_title")}</p><p className="truncate text-xs text-[#9A8B7B]">{buyerName(s(o, "buyer_id"))} · {s(o, "placed_on")}</p></div>
