                          {s(o, "status") === "placed" && <span className="text-xs text-[#9A8B7B]">Waiting for payment</span>}
                          {s(o, "status") === "delivered" && <span className="flex items-center gap-1 text-xs" style={{ color: SAGE }}><Check size={14} />Completed</span>}
                        </div>
                      </motion.div>
                    ))}
