              <div className="flex items-center justify-between px-6 pb-2 pt-6"><h2 className="text-2xl" style={{ fontFamily: SERIF }}>{sheet.id ? "Edit product" : "New product"}</h2><button onClick={() => setSheet(null)} aria-label="Close" className="grid h-10 w-10 place-items-center rounded-full bg-white"><X size={18} /></button></div>
              <div className="space-y-3 overflow-y-auto px-6 pb-3 pt-2">
                {form.photo ? <Img src={form.photo} alt="Preview" className="h-36 w-full rounded-2xl" /> : null}
                <input aria-label="Title" placeholder="Title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className={input} />
                <textarea aria-label="Description" placeholder="Tell the story of this piece" rows={3} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} className={input} />
                <div className="-mt-1">
                  <motion.button type="button" whileTap={{ scale: 0.96 }} onClick={() => void describe()} disabled={aiBusy} className="inline-flex items-center gap-2 rounded-full border border-[#D9B99A] bg-[#F7EBDD] px-4 py-2 text-sm font-medium text-[#8A5E3B] disabled:opacity-70">
                    <motion.span animate={aiBusy && !reduce ? { rotate: 360 } : { rotate: 0 }} transition={aiBusy ? { repeat: Infinity, duration: 1.6, ease: "linear" } : { duration: 0 }} className="inline-flex"><Sparkles size={15} /></motion.span>
                    {aiBusy ? "Writing…" : "Describe my piece"}
                  </motion.button>
                  <AnimatePresence>
                    {aiNote && <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="mt-2 text-sm text-[#8C3A25]" role="status">{aiNote}</motion.p>}
                    {aiDraft && (
                      <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mt-3 rounded-2xl border border-[#E6DACB] bg-white p-3">
                        <p className="mb-1 text-[10px] uppercase tracking-[0.24em] text-[#9A8B7B]">Suggested description · edit freely</p>
                        <textarea aria-label="Suggested description" rows={3} value={aiDraft} onChange={(e) => setAiDraft(e.target.value)} className="w-full resize-none bg-transparent text-sm leading-relaxed outline-none" />
                        <div className="mt-2 flex justify-end gap-2">
                          <button type="button" onClick={() => setAiDraft("")} className="rounded-full px-4 py-1.5 text-sm text-[#8A7B6B]">Dismiss</button>
                          <button type="button" onClick={() => { setForm({ ...form, description: aiDraft.trim() }); setAiDraft(""); }} className="flex items-center gap-1.5 rounded-full px-4 py-1.5 text-sm font-medium text-white" style={{ background: CLAY }}><Check size={14} />Use this</button>
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
                <div className="grid grid-cols-3 gap-3">
                  <input aria-label="Price" type="number" min={0} placeholder="Price $" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} className={input} />
                  <input aria-label="Stock" type="number" min={0} placeholder="Stock" value={form.stock} onChange={(e) => setForm({ ...form, stock: e.target.value })} className={input} />
                  <select aria-label="Category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} className={input}>{CATS.map((c) => <option key={c} value={c}>{cap(c)}</option>)}</select>
                </div>
                <input aria-label="Photo URL" placeholder="Main photo URL (https://…)" value={form.photo} onChange={(e) => setForm({ ...form, photo: e.target.value })} className={input} />
                <div className="grid grid-cols-2 gap-3">
                  <input aria-label="Second photo URL" placeholder="2nd photo URL" value={form.photo_2} onChange={(e) => setForm({ ...form, photo_2: e.target.value })} className={input} />
                  <input aria-label="Third photo URL" placeholder="3rd photo URL" value={form.photo_3} onChange={(e) => setForm({ ...form, photo_3: e.target.value })} className={input} />
                </div>
                <input aria-label="Materials" placeholder="Materials" value={form.materials} onChange={(e) => setForm({ ...form, materials: e.target.value })} className={input} />
              </div>
              <div className="px-6 pb-6 pt-3"><motion.button whileTap={{ scale: 0.97 }} onClick={() => void save()} disabled={saving} className="w-full rounded-2xl py-4 text-[15px] font-medium text-white shadow-[0_14px_28px_-12px_rgba(181,131,90,0.95)] disabled:opacity-60" style={{ background: CLAY }}>{saving ? "Saving…" : sheet.id ? "Save changes" : "Submit for approval"}</motion.button></div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {toast && <motion.div key={toast.text} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 10 }} className="fixed bottom-24 left-1/2 z-[60] -translate-x-1/2 rounded-2xl px-5 py-3 text-sm text-white shadow-xl lg:bottom-8" style={{ background: toast.bad ? "#8C3A25" : INK }}>{toast.text}</motion.div>}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { motion, AnimatePresence, LayoutGroup, animate, useReducedMotion } from "motion/react";
import { ShieldCheck, TrendingUp, LogOut, Check, EyeOff, Clock, Package, DollarSign, Users, ShoppingBag } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle };

const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif";
const INK = "#2B2420";
const SAND = "#FBF7F2";
const SAGE = "#8A9A82";
const CLAY = "hsl(var(--primary))";
const EASE = [0.22, 1, 0.36, 1] as const;
const SH = "shadow-[0_1px_2px_rgba(60,40,20,0.06),0_16px_36px_-20px_rgba(60,40,20,0.45)]";

const s = (r: R | undefined, k: string): string => (r && r[k] != null ? String(r[k]) : "");
const n = (r: R | undefined, k: string): number => (r ? Number(r[k]) || 0 : 0);
const money = (v: number) => "$" + v.toLocaleString("en-US", { maximumFractionDigits: 0 });
const cap = (t: string) => t.charAt(0).toUpperCase() + t.slice(1);

function Counter({ value, money: asMoney = true }: { value: number; money?: boolean }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(0);
  const last = useRef(0);
  useEffect(() => {
    if (reduce) { last.current = value; setV(value); return; }
    const c = animate(last.current, value, { duration: 1.2, ease: "easeOut", onUpdate: (x) => { last.current = x; setV(x); } });
    return () => c.stop();
  }, [value, reduce]);
  return <span style={{ fontFamily: SERIF }}>{asMoney ? money(v) : Math.round(v).toLocaleString("en-US")}</span>;
}

function Img({ src, className, alt }: { src: string; className?: string; alt: string }) {
  return (
    <div className={"relative overflow-hidden " + (className || "")} style={{ background: "linear-gradient(135deg,#EADFD0,#D9C7B0)" }}>
      {src ? <img src={src} alt={alt} loading="lazy" className="absolute inset-0 h-full w-full object-cover" /> : null}
    </div>
  );
}

const STATUS = ["placed", "paid", "shipped", "delivered"];

export default function AdminConsole({ app }: Props) {
  const reduce = useReducedMotion();
  const [tab, setTab] = useState("approvals");
  const [toast, setToast] = useState("");
  const [busy, setBusy] = useState("");
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(""), 3000); return () => clearTimeout(t); }, [toast]);

  const products = (app?.rows("product") ?? []) as R[];
  const sellers = (app?.rows("seller") ?? []) as R[];
  const orders = (app?.rows("order") ?? []) as R[];
  const sellerName = (id: string) => s(sellers.find((x) => s(x, "id") === id), "shop_name") || "Maker";
  const pending = products.filter((p) => s(p, "status") === "pending");
  const live = products.filter((p) => s(p, "status") === "approved").length;
  const paidOrders = orders.filter((o) => s(o, "status") !== "placed");
  const gmv = paidOrders.reduce((a, o) => a + n(o, "total"), 0);
  const avg = paidOrders.length ? gmv / paidOrders.length : 0;
  const bySeller = useMemo(() => {
    const m: Record<string, number> = {};
    for (const o of paidOrders) m[s(o, "seller_id")] = (m[s(o, "seller_id")] || 0) + n(o, "total");
    return Object.entries(m).sort((a, b) => b[1] - a[1]);
  }, [paidOrders.length, sellers.length]);
  const topMax = Math.max(1, ...bySeller.map((x) => x[1]));
  const byStatus = STATUS.map((st) => ({ st, c: orders.filter((o) => s(o, "status") === st).length }));
  const maxStatus = Math.max(1, ...byStatus.map((x) => x.c));
  const recent = orders.slice().sort((a, b) => s(b, "placed_on").localeCompare(s(a, "placed_on"))).slice(0, 6);

  const decide = async (p: R, status: string) => {
    setBusy(s(p, "id"));
    try { await app?.update("product", s(p, "id"), { status }); setToast(status === "approved" ? s(p, "title") + " is now live" : s(p, "title") + " was hidden"); }
    catch (e) { setToast(e instanceof Error ? e.message : "Couldn't update"); }
    setBusy("");
  };

  const nav = [{ id: "approvals", label: "Approvals", Icon: ShieldCheck, badge: pending.length }, { id: "sales", label: "Sales", Icon: TrendingUp }];

  return (
    <div className="min-h-screen w-full lg:grid lg:grid-cols-[250px_1fr]" style={{ background: SAND, color: INK, fontFamily: "ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif" }}>
      <aside className="hidden border-r border-[#EADFD0] bg-[#F7F0E7] p-6 lg:flex lg:min-h-screen lg:flex-col">
        <div className="flex items-center gap-2.5"><span className="grid h-9 w-9 place-items-center rounded-full text-lg text-white" style={{ background: CLAY, fontFamily: SERIF }}>A</span><span className="text-2xl" style={{ fontFamily: SERIF }}>Curator</span></div>
        <LayoutGroup id="aside">
          <nav className="mt-10 space-y-1">
            {nav.map((t) => (
              <button key={t.id} onClick={() => setTab(t.id)} className="relative flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm font-medium" style={{ color: tab === t.id ? INK : "#8A7B6B" }}>
                {tab === t.id && <motion.span layoutId="apill" className="absolute inset-0 rounded-2xl bg-white shadow-sm" transition={{ type: "spring", stiffness: 420, damping: 34 }} />}
                <t.Icon size={18} className="relative" /><span className="relative">{t.label}</span>
                {t.badge ? <span className="relative ml-auto rounded-full px-2 py-0.5 text-[11px] text-white" style={{ background: CLAY }}>{t.badge}</span> : null}
              </button>
            ))}
          </nav>
        </LayoutGroup>
        <div className="mt-auto space-y-1">
          <button onClick={() => app?.navigate("/team")} className="flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm text-[#8A7B6B]"><Users size={18} />Team & access</button>
          <button onClick={() => void app?.auth.signOut()} className="flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm text-[#8A7B6B]"><LogOut size={18} />Sign out</button>
        </div>
      </aside>

      <div className="min-w-0 pb-28 lg:pb-12">
        <header className="flex items-center justify-between px-5 pb-2 pt-6 lg:px-10 lg:pt-9">
          <div><p className="text-[11px] uppercase tracking-[0.28em] text-[#9A8B7B]">Atelier admin</p><h1 className="text-3xl lg:text-4xl" style={{ fontFamily: SERIF }}>{tab === "approvals" ? "Approve new pieces" : "Marketplace sales"}</h1></div>
          <button onClick={() => void app?.auth.signOut()} aria-label="Sign out" className="grid h-11 w-11 place-items-center rounded-full border border-[#EADFD0] bg-white text-[#8A7B6B] lg:hidden"><LogOut size={18} /></button>
        </header>

        <main className="px-5 pt-4 lg:px-10">
          <AnimatePresence mode="wait" initial={false}>
            {tab === "approvals" ? (
              <motion.div key="a" initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.4, ease: EASE }}>
                <p className="mb-5 flex items-center gap-2 text-sm text-[#8A7B6B]"><Clock size={15} /><Counter value={pending.length} money={false} /> waiting for review · {live} live in the shop</p>
                {pending.length === 0 ? (
                  <div className="rounded-3xl border border-dashed border-[#DCCDB9] py-20 text-center"><motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", stiffness: 260, damping: 14 }} className="mx-auto grid h-16 w-16 place-items-center rounded-full text-white" style={{ background: SAGE }}><Check size={30} /></motion.div><p className="mt-4 text-2xl" style={{ fontFamily: SERIF }}>All caught up</p><p className="mt-1 text-sm text-[#8A7B6B]">New submissions from makers will land here.</p></div>
                ) : (
                  <div className="grid gap-5 lg:grid-cols-2">
                    <AnimatePresence mode="popLayout">
                      {pending.map((p, i) => (
                        <motion.div key={s(p, "id")} layout initial={reduce ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, x: 80, scale: 0.95 }} transition={{ delay: i * 0.08, duration: 0.5, ease: EASE }} className={"overflow-hidden rounded-[28px] bg-white " + SH}>
                          <Img src={s(p, "photo")} alt={s(p, "title")} className="h-52 w-full" />
                          <div className="p-5">
                            <p className="text-[11px] uppercase tracking-[0.2em] text-[#9A8B7B]">{sellerName(s(p, "seller_id"))} · {cap(s(p, "category"))}</p>
                            <div className="mt-1 flex items-start justify-between gap-3"><h3 className="text-2xl leading-tight" style={{ fontFamily: SERIF }}>{s(p, "title")}</h3><span className="text-lg font-medium">{money(n(p, "price"))}</span></div>
                            <p className="mt-2 line-clamp-3 text-sm leading-relaxed text-[#6B5E51]">{s(p, "description")}</p>
                            <p className="mt-2 text-xs text-[#9A8B7B]">{n(p, "stock")} in stock · {s(p, "materials")}</p>
                            <div className="mt-4 flex gap-3">
                              <motion.button whileTap={{ scale: 0.95 }} whileHover={{ y: -1 }} disabled={busy === s(p, "id")} onClick={() => void decide(p, "approved")} className="flex flex-1 items-center justify-center gap-2 rounded-full py-3 text-sm font-medium text-white disabled:opacity-60" style={{ background: CLAY }}><Check size={16} />Approve</motion.button>
                              <motion.button whileTap={{ scale: 0.95 }} disabled={busy === s(p, "id")} onClick={() => void decide(p, "hidden")} className="flex items-center justify-center gap-2 rounded-full border border-[#E3D6C4] px-5 py-3 text-sm font-medium text-[#6B5E51] disabled:opacity-60"><EyeOff size={16} />Hide</motion.button>
                            </div>
                          </div>
                        </motion.div>
                      ))}
                    </AnimatePresence>
                  </div>
                )}
              </motion.div>
            ) : (
              <motion.div key="s" initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.4, ease: EASE }}>
                <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
                  {[{ l: "Gross sales", node: <Counter value={gmv} />, Icon: DollarSign, hero: true }, { l: "Orders", node: <Counter value={orders.length} money={false} />, Icon: ShoppingBag }, { l: "Avg. order", node: <Counter value={avg} />, Icon: TrendingUp }, { l: "Live pieces", node: <Counter value={live} money={false} />, Icon: Package }].map((x, i) => (
                    <motion.div key={x.l} initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08, ease: EASE }} className={"rounded-3xl p-5 " + (x.hero ? "col-span-2 text-[#FBF7F2] lg:col-span-1" : "bg-white ") + SH} style={x.hero ? { background: "linear-gradient(135deg,#B5835A,#8E6240 70%,#6F7B68)" } : undefined}>
                      <x.Icon size={18} className={x.hero ? "opacity-80" : "text-[#B5835A]"} />
                      <p className="mt-3 text-4xl">{x.node}</p>
                      <p className={"mt-1 text-xs " + (x.hero ? "opacity-80" : "text-[#9A8B7B]")}>{x.l}</p>
                    </motion.div>
                  ))}
                </div>
                <div className="mt-6 grid gap-5 lg:grid-cols-2">
                  <div className={"rounded-[28px] bg-white p-6 " + SH}>
                    <h2 className="text-xl" style={{ fontFamily: SERIF }}>Sales by maker</h2>
                    <div className="mt-4 space-y-3">
                      {bySeller.length === 0 ? <p className="text-sm text-[#8A7B6B]">No sales yet.</p> : bySeller.map(([id, v], i) => (
                        <div key={id}><div className="mb-1 flex justify-between text-sm"><span>{sellerName(id)}</span><span className="font-medium">{money(v)}</span></div><div className="h-2.5 overflow-hidden rounded-full bg-[#F1E6D8]"><motion.div initial={reduce ? false : { width: 0 }} animate={{ width: (v / topMax) * 100 + "%" }} transition={{ delay: 0.2 + i * 0.08, duration: 0.9, ease: EASE }} className="h-full rounded-full" style={{ background: i === 0 ? CLAY : SAGE }} /></div></div>
                      ))}
                    </div>
                  </div>
                  <div className={"rounded-[28px] bg-white p-6 " + SH}>
                    <h2 className="text-xl" style={{ fontFamily: SERIF }}>Order pipeline</h2>
                    <div className="mt-5 flex h-40 items-end gap-4">
                      {byStatus.map((x, i) => (
                        <div key={x.st} className="flex flex-1 flex-col items-center gap-2"><span className="text-sm font-medium">{x.c}</span><motion.div initial={reduce ? false : { height: 0 }} animate={{ height: Math.max(8, (x.c / maxStatus) * 100) }} transition={{ delay: 0.3 + i * 0.1, duration: 0.8, ease: EASE }} className="w-full rounded-t-2xl" style={{ background: i % 2 ? SAGE : "#C9A27F" }} /><span className="text-[11px] text-[#8A7B6B]">{cap(x.st)}</span></div>
                      ))}
                    </div>
                  </div>
                </div>
                <h2 className="mb-3 mt-8 text-2xl" style={{ fontFamily: SERIF }}>Recent orders</h2>
                <div className={"overflow-hidden rounded-[28px] bg-white " + SH}>
                  {recent.map((o, i) => (
                    <motion.div key={s(o, "id")} initial={reduce ? false : { opacity: 0, x: -12 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.1 + i * 0.05 }} className="flex items-center gap-3 border-b border-[#F1E6D8] px-5 py-4 last:border-0">
                      <div className="min-w-0 flex-1"><p className="truncate text-[15px]" style={{ fontFamily: SERIF }}>{s(o, "product_title")}</p><p className="truncate text-xs text-[#9A8B7B]">{sellerName(s(o, "seller_id"))} · {s(o, "placed_on")}</p></div>
                      <span className="rounded-full bg-[#F1E6D8] px-2.5 py-1 text-[11px] text-[#8A5E3B]">{cap(s(o, "status"))}</span>
                      <span className="w-16 text-right font-medium">{money(n(o, "total"))}</span>
                    </motion.div>
                  ))}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </main>
      </div>

      <nav className="fixed inset-x-0 bottom-4 z-30 flex justify-center px-4 lg:hidden">
        <LayoutGroup id="atabs">
          <div className="flex gap-1 rounded-full border border-white/60 p-1.5 shadow-[0_18px_40px_-14px_rgba(60,40,20,0.55)] backdrop-blur-xl" style={{ background: "rgba(251,247,242,0.9)" }}>
            {nav.map((t) => (
              <button key={t.id} onClick={() => setTab(t.id)} className="relative flex items-center gap-2 rounded-full px-5 py-3 text-sm font-medium" style={{ color: tab === t.id ? "#fff" : "#7A6C5E" }}>
                {tab === t.id && <motion.span layoutId="ampill" className="absolute inset-0 rounded-full" style={{ background: INK }} transition={{ type: "spring", stiffness: 420, damping: 32 }} />}
                <t.Icon size={17} className="relative" /><span className="relative">{t.label}</span>
                {t.badge ? <span className="relative rounded-full px-1.5 text-[11px]" style={{ background: CLAY, color: "#fff" }}>{t.badge}</span> : null}
              </button>
            ))}
          </div>
        </LayoutGroup>
      </nav>

      <AnimatePresence>
        {toast && <motion.div key={toast} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 10 }} className="fixed bottom-24 left-1/2 z-[60] -translate-x-1/2 rounded-2xl px-5 py-3 text-sm text-white shadow-xl lg:bottom-8" style={{ background: INK }}>{toast}</motion.div>}
      </AnimatePresence>
    </div>
  );
}
